window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[265]={"id":"265","numero":265,"titre":"Lithiase urinaire","objectifs":[{"id":"265-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la lithiase et du calcul urinaires","contenu":"<p>La <span class=\"kw-def\">lithiase urinaire</span> est une <span class=\"kw-def\">maladie multifactorielle</span> aboutissant à la formation de <span class=\"kw-def\">calculs</span> dans <span class=\"kw-clinique\">les</span> voies urinaires : <span class=\"kw-clinique\">cavités rénales</span>, <span class=\"kw-clinique\">uretères</span>, et plus rarement <span class=\"kw-clinique\">vessie</span> et <span class=\"kw-clinique\">urètre</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Lithiase ≠ calcul.</strong> Le <span class=\"kw-def\">calcul</span> est la concrétion ; la <span class=\"kw-def\">lithiase</span> est la maladie qui le génère. Il faut <strong>traiter le calcul</strong>, puis <strong>porter le diagnostic de lithiase</strong> pour prévenir <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">récidives</span>.</div>\n      <p><strong>Composition d'un calcul</strong> — composés <span class=\"kw-def\">minéraux</span> (calcium, phosphates, magnésium) et/ou <span class=\"kw-def\">organiques</span> (oxalate, acide urique, cystine) :</p>\n      <ul>\n        <li><strong>1 seul composé</strong> dans <span class=\"kw-chiffre\">10 %</span> des cas (ex. <span class=\"kw-def\">cystine</span>)</li>\n        <li><strong>Plusieurs composés</strong> dans <span class=\"kw-chiffre\">90 %</span> des cas (<span class=\"kw-chiffre\">≥ 3</span> composés dans <span class=\"kw-chiffre\">80 %</span>, avec un composant majoritaire — ex. <span class=\"kw-def\">oxalate de calcium</span>)</li>\n      </ul>\n      <p>Taille variable, de quelques <span class=\"kw-chiffre\">millimètres</span> à plusieurs <span class=\"kw-chiffre\">centimètres</span>. Le <span class=\"kw-def\">calcul coralliforme</span> occupe la <strong>totalité des cavités pyélocalicielles</strong>.</p>","frequence":0},{"id":"265-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie de la lithiase urinaire","contenu":"<ul>\n        <li>Touche <span class=\"kw-chiffre\">5–10 %</span> de la population des <span class=\"kw-etio\">pays industrialisés</span>, avec une <span class=\"kw-clinique\">incidence en augmentation</span> (liée aux <span class=\"kw-etio\">habitudes alimentaires</span>)</li>\n        <li>En France : <span class=\"kw-chiffre\">170 000</span> épisodes aigus de <span class=\"kw-clinique\">colique néphrétique</span> par an, dont <span class=\"kw-chiffre\">90 %</span> liés à des <span class=\"kw-def\">calculs</span></li>\n        <li><strong>Sex-ratio</strong> : <span class=\"kw-clinique\">prédominance masculine</span> <span class=\"kw-chiffre\">2 H / 1 F</span></li>\n        <li><strong>Âge moyen du 1ᵉʳ calcul</strong> : <span class=\"kw-chiffre\">35 ans</span> chez l'homme, <span class=\"kw-chiffre\">40 ans</span> chez la femme</li>\n        <li><strong><span class=\"kw-clinique\">Récidive</span></strong> (en l'absence de <span class=\"kw-def\">traitement préventif</span>) : <span class=\"kw-chiffre\">50 %</span> à<span class=\"kw-chiffre\"> 5 ans</span>, <span class=\"kw-chiffre\">70 %</span> à<span class=\"kw-chiffre\"> 10 ans</span> → justifie la recherche et la correction des <span class=\"kw-def\">facteurs de lithogenèse</span></li>\n      </ul>","frequence":0},{"id":"265-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence des différents types de calculs","contenu":"<p>L'<span class=\"kw-def\">oxalate de calcium</span> est de loin le calcul le plus fréquent (≈ <span class=\"kw-chiffre\">70 %</span> tous types confondus). La <span class=\"kw-imagerie\">densité TDM</span> (unités Hounsfield) oriente la composition et la <span class=\"kw-clinique\">dureté</span> du calcul.</p>\n      <table >\n        <thead><tr><th>Type de calcul</th><th>Fréquence</th><th>Densité <span class=\"kw-imagerie\">TDM</span></th><th>Principal facteur favorisant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Oxalate de Ca — whewellite</span> (monohydraté)</td><td><span class=\"kw-chiffre\">50 %</span></td><td><span class=\"kw-imagerie\">1200–1700 UH</span></td><td><span class=\"kw-etio\">Hyperoxalurie</span></td></tr>\n          <tr><td><span class=\"kw-def\">Oxalate de Ca — weddellite</span> (dihydraté)</td><td><span class=\"kw-chiffre\">20 %</span></td><td><span class=\"kw-imagerie\">900–1300 UH</span></td><td><span class=\"kw-etio\">Hypercalciurie</span></td></tr>\n          <tr><td><span class=\"kw-def\">Phosphates de calcium</span> (carbapatite, brushite)</td><td><span class=\"kw-chiffre\">15 %</span></td><td><span class=\"kw-imagerie\">1300–1900 UH</span></td><td><span class=\"kw-etio\">Hypercalciurie</span> ; <span class=\"kw-etio\">pH alcalin</span></td></tr>\n          <tr><td><span class=\"kw-def\">Acide urique</span></td><td><span class=\"kw-chiffre\">10 %</span></td><td><span class=\"kw-imagerie\">350–500 UH</span> (radio-transparent)</td><td><span class=\"kw-etio\">pH urinaire acide</span> ; hyperuricémie</td></tr>\n          <tr><td><span class=\"kw-def\">Cystine</span></td><td><span class=\"kw-chiffre\">1,5 %</span></td><td><span class=\"kw-imagerie\">600–850 UH</span></td><td><span class=\"kw-etio\">Cystinurie</span> (autosomique récessive)</td></tr>\n          <tr><td><span class=\"kw-def\">Struvite</span> (phospho-ammoniaco-magnésien)</td><td><span class=\"kw-chiffre\">1 %</span></td><td><span class=\"kw-imagerie\">600–900 UH</span></td><td><span class=\"kw-etio\">Infection</span> à germes uréasiques</td></tr>\n          <tr><td><span class=\"kw-def\">Urates</span></td><td><span class=\"kw-chiffre\">0,5 %</span></td><td>—</td><td><span class=\"kw-etio\">pH alcalin</span> ; hyperuricémie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère <span class=\"kw-imagerie\">TDM</span>.</strong> Calculs <strong><span class=\"kw-clinique\">les</span> plus denses et durs</strong> = <span class=\"kw-def\">brushite</span> et <span class=\"kw-def\">oxalate monohydraté</span> (<span class=\"kw-imagerie\">&gt; 1200 UH</span>, résistants à la LEC) ; <strong>radio-transparents</strong> = <span class=\"kw-def\">acide urique</span>, urates, certains <span class=\"kw-etio\">médicamenteux</span> (invisibles sur l'<span class=\"kw-imagerie\">ASP</span>).</div>","frequence":2},{"id":"265-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux facteurs lithogènes","contenu":"<p><strong>Lithogenèse</strong> — cascade physiopathologique de formation du calcul :</p>\n      <ol>\n        <li><span class=\"kw-def\">Sursaturation urinaire</span> : concentration d'un soluté au-delà des capacités de dissolution (dépend de la <span class=\"kw-bio\">concentration</span>, du <span class=\"kw-bio\">pH urinaire</span>, des <span class=\"kw-def\">inhibiteurs de cristallisation</span> et de la <span class=\"kw-clinique\">stase</span>)</li>\n        <li><span class=\"kw-def\">Germination (nucléation)</span> cristalline</li>\n        <li><span class=\"kw-def\">Croissance</span>, puis <span class=\"kw-def\">agrégation</span> et <span class=\"kw-def\">agglomération</span> des cristaux</li>\n        <li><span class=\"kw-def\">Rétention</span> des particules → <span class=\"kw-def\">croissance du calcul</span></li>\n      </ol>\n      <p><span class=\"kw-clinique\">Les</span> sujets lithiasiques présentent un <strong>déséquilibre promoteurs / inhibiteurs</strong>. <span class=\"kw-def\">Inhibiteurs de cristallisation</span> : <span class=\"kw-bio\">citrate</span>, <span class=\"kw-bio\">magnésium</span>, zinc (faible PM) ; glycosaminoglycanes, glycoprotéines (haut PM).</p>\n      <table >\n        <thead><tr><th>Facteur lithogène</th><th>Mécanisme / détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Alimentaires</span></td><td>\n            <strong>Diurèse faible :</strong> apports liquidiens insuffisants<br>\n            <strong>↓ fibres :</strong> perte d'apport en <span class=\"kw-bio\">citrate</span> (inhibiteur)<br>\n            <strong>Excès :</strong> produits laitiers, protéines animales, sel (→ <span class=\"kw-clinique\">hypercalciurie</span>) ; purines (→ hyperuricémie) ; sucres rapides et <span class=\"kw-bio\">fructose</span> ; aliments riches en <span class=\"kw-bio\">oxalates</span> (épinards, oseille, rhubarbe, chocolat, thé, fruits secs, vitamine C)</td></tr>\n          <tr><td><span class=\"kw-etio\">Familiaux / génétiques</span></td><td>Histoire familiale chez <span class=\"kw-chiffre\">&gt; 1/3</span> des lithiasiques, transmission le plus souvent <span class=\"kw-def\">autosomique récessive</span> ; la <span class=\"kw-def\">cystinurie</span> est la plus fréquente des lithiases d'origine <span class=\"kw-etio\">génétique</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Infection urinaire</span></td><td>Calculs de <span class=\"kw-def\">struvite</span> favorisés par <span class=\"kw-clinique\">les</span> <strong>germes uréasiques</strong> (l'<span class=\"kw-bio\">uréase</span> clive l'<span class=\"kw-bio\">urée</span> urinaire en <span class=\"kw-bio\">ammoniac + CO₂</span>) : <span class=\"kw-etio\">Proteus mirabilis</span>, <span class=\"kw-etio\">Klebsiella pneumoniae</span>, <span class=\"kw-etio\">Pseudomonas aeruginosa</span></td></tr>\n          <tr><td><span class=\"kw-etio\">pH urinaire</span></td><td><span class=\"kw-bio\">pH</span> normal des urines <span class=\"kw-chiffre\">5,8</span><br><strong>pH acide</strong> (~<span class=\"kw-chiffre\">5</span>) → <span class=\"kw-def\">acide urique</span>, <span class=\"kw-def\">cystine</span>, oxalate de calcium<br><strong>pH alcalin</strong> (~<span class=\"kw-chiffre\">7</span>) → <span class=\"kw-etio\">infection</span> et calculs phosphocalciques</td></tr>\n          <tr><td><span class=\"kw-etio\">Anomalies urologiques</span> (stase)</td><td><span class=\"kw-def\">Syndrome de la jonction pyélo-urétérale</span>, rein en fer à cheval, diverticules caliciels, urétérocèle, méga-uretère, duplicité ; <span class=\"kw-def\">maladie de Cacchi-Ricci</span> (ectasie canaliculaire pré-calicielle)</td></tr>\n          <tr><td><span class=\"kw-etio\">Médicaments</span></td><td>Modification des urines (<span class=\"kw-ttt\">vitamine D</span> → hypercalciurie) ; précipitation de la molécule : <span class=\"kw-ttt\">indinavir</span>, <span class=\"kw-ttt\">atazanavir</span> (radio-transparents) ; plus rarement <span class=\"kw-ttt\">cotrimoxazole</span>, allopurinol, <span class=\"kw-ttt\">amiodarone</span>, thiazidiques</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"265-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition de la colique néphrétique","contenu":"<p>La <span class=\"kw-def\">colique néphrétique</span> (CN) est un <span class=\"kw-clinique\">syndrome douloureux aigu lombo-abdominal</span> lié à la <strong>mise en tension brutale de la voie excrétrice supérieure</strong>, en amont d'une <span class=\"kw-def\">obstruction aiguë ± complète</span> de la voie excrétrice — quelle qu'en soit la cause.</p>\n      <div class=\"callout callout-info\"><strong>Calcul = cause la plus fréquente, mais non exclusive.</strong> Tout obstacle sur la voie excrétrice peut donner une CN. Le <span class=\"kw-def\">syndrome de la jonction pyélo-urétérale</span> en est la <strong>2ᵉ cause</strong> (douleur par tension pyélique ; <span class=\"kw-imagerie\">TDM</span> : dilatation du bassinet ; <span class=\"kw-imagerie\">scintigraphie MAG3</span> pour confirmer l'obstruction).</div>\n      <p><strong>Diagnostics différentiels</strong> à connaître :</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Urologiques</span></td><td><span class=\"kw-clinique\">Pyélonéphrite aiguë</span> ; <span class=\"kw-clinique\">infarctus rénal</span> ; <span class=\"kw-clinique\">nécrose papillaire</span> ; douleur scrotale aiguë</td></tr>\n          <tr><td><span class=\"kw-etio\">Non urologiques (urgences)</span></td><td><span class=\"kw-alerte\">Fissuration d'anévrisme de l'aorte</span> ; <span class=\"kw-alerte\">dissection aortique</span> ; <span class=\"kw-alerte\">grossesse extra-utérine</span> ; torsion de kyste ovarien ; torsion du cordon spermatique</td></tr>\n          <tr><td><span class=\"kw-etio\">Digestives / autres</span></td><td><span class=\"kw-clinique\">Pancréatite aiguë</span> ; <span class=\"kw-clinique\">colique hépatique</span> ; <span class=\"kw-clinique\">infarctus</span> mésentérique ; <span class=\"kw-clinique\">appendicite</span> ; pneumopathie basale ; <span class=\"kw-clinique\">lombalgie aiguë</span></td></tr>\n        </tbody>\n      </table>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/ureteropelvic-junction-obstruction","label":"Radiopaedia : Syndrome de jonction pyélo-urétérale"}]},{"id":"265-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les facteurs favorisants de la colique néphrétique","contenu":"<p>Circonstances déclenchantes favorisant la <span class=\"kw-clinique\">migration</span> d'un <span class=\"kw-def\">calcul</span> et donc la <span class=\"kw-def\">colique néphrétique</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Voyage récent et prolongé</span> ; <span class=\"kw-etio\">immobilisation prolongée</span></li>\n        <li><span class=\"kw-etio\">Déshydratation</span>, <span class=\"kw-etio\">chaleur</span>, <span class=\"kw-etio\">boissons insuffisantes</span></li>\n        <li><span class=\"kw-etio\">Activité physique</span> intense</li>\n        <li><span class=\"kw-etio\">Écarts de régime</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Logique commune.</strong> Ces facteurs convergent vers une <span class=\"kw-clinique\">réduction de la diurèse</span> et une <span class=\"kw-clinique\">concentration des urines</span>, qui favorisent la <span class=\"kw-clinique\">mobilisation</span> d'un <span class=\"kw-def\">calcul préexistant</span> et la mise en tension de la <span class=\"kw-clinique\">voie excrétrice</span>.</div>","frequence":0},{"id":"265-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les aspects cliniques de la colique néphrétique simple","contenu":"<p><strong>Caractéristiques de la douleur</strong> de la <span class=\"kw-def\">colique néphrétique simple</span> :</p>\n      <ul>\n        <li><strong>Début</strong> <span class=\"kw-clinique\">brutal</span>, intensité <span class=\"kw-clinique\">très intense</span>, <span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">paroxystique</span>, type <span class=\"kw-clinique\">torsion</span></li>\n        <li><span class=\"kw-clinique\">Unilatérale</span>, <span class=\"kw-clinique\">lombaire</span> ou de l'angle costo-vertébral</li>\n        <li><strong><span class=\"kw-clinique\">Irradiation</span></strong> antérieure et oblique vers la <span class=\"kw-clinique\">racine de la cuisse</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">OGE</span></li>\n        <li><strong>Aucune position <span class=\"kw-ttt\">antalgique</span></strong> ; douleur à la palpation et à la percussion de la fosse lombaire</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>L'arrêt brutal de la douleur</strong> traduit soit l'<span class=\"kw-clinique\">expulsion du calcul</span>, soit une <span class=\"kw-alerte\">rupture d'un fornix rénal</span> avec extravasation d'urine en péri-rénal.</div>\n      <p><strong>Signes associés</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Anxiété</span>, <span class=\"kw-clinique\">agitation</span> (impossibilité de trouver une position <span class=\"kw-ttt\">antalgique</span>)</li>\n        <li>Digestifs (<span class=\"kw-def\">iléus réflexe</span>) : <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">constipation</span></li>\n        <li>Urinaires : <span class=\"kw-clinique\">pollakiurie</span>, <span class=\"kw-clinique\">impériosités</span>, <span class=\"kw-clinique\">dysurie</span>, <span class=\"kw-bio\">hématurie microscopique</span> à la <span class=\"kw-bio\">BU</span> (<span class=\"kw-chiffre\">95 %</span> à <span class=\"kw-chiffre\">J1</span>)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Signes négatifs de la forme simple :</strong> <strong>pas de <span class=\"kw-clinique\">fièvre</span></strong>, abdomen souple sans défense, touchers pelviens normaux. Leur disparition fait basculer vers une <strong>forme compliquée</strong>.</div>","frequence":2},{"id":"265-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les aspects cliniques de la colique néphrétique compliquée","contenu":"<div class=\"callout callout-danger\"><strong>Colique néphrétique compliquée = <span class=\"kw-alerte\">urgence</span> (≈<span class=\"kw-chiffre\"> 5 %</span> des cas).</strong> Justifie un <strong>avis spécialisé + <span class=\"kw-alerte\">hospitalisation</span> en urgence</strong> 🏥. Quatre situations à reconnaître : <span class=\"kw-def\">terrain</span> à risque, <span class=\"kw-clinique\">fièvre</span>, oligo-anurie/IRA, forme hyperalgique.</div>\n      <table >\n        <thead><tr><th>Forme compliquée</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Terrain à risque</span></td><td><span class=\"kw-alerte\">Grossesse</span> ; patient <span class=\"kw-clinique\">VIH</span> sous antiprotéases (<span class=\"kw-ttt\">indinavir</span>, <span class=\"kw-ttt\">atazanavir</span>) ; <span class=\"kw-alerte\">rein unique</span> ; uropathie connue ; <span class=\"kw-clinique\">insuffisance rénale chronique</span> ; rein transplanté</td></tr>\n          <tr><td><span class=\"kw-alerte\">Fièvre &gt; 38 °C</span></td><td><span class=\"kw-def\">PNA obstructive</span> = rétention d'urine purulente au-dessus de l'obstacle → risque d'<span class=\"kw-alerte\">abcès du rein</span> et de <span class=\"kw-alerte\">septicémie / choc septique</span> à gram négatif</td></tr>\n          <tr><td><span class=\"kw-alerte\">Oligo-anurie / IRA</span></td><td>IRA compliquant une PNA ou un <span class=\"kw-alerte\">choc septique</span> ; <span class=\"kw-def\">IRA obstructive</span> (obstacle bilatéral, ou unilatéral sur <span class=\"kw-alerte\">rein unique</span> anatomique ou fonctionnel)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Forme hyperalgique</span></td><td>Douleur <strong>résistante au traitement médical bien conduit</strong></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie · 161 — <span class=\"kw-clinique\">Infection urinaire</span></em></p>","frequence":5},{"id":"265-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les autres aspects cliniques des calculs urinaires","contenu":"<p>En dehors de la <span class=\"kw-def\">colique néphrétique</span>, un <span class=\"kw-def\">calcul</span> peut se révéler par :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Découverte fortuite</span> (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">scanner</span>)</li>\n        <li>Douleurs atypiques ou <span class=\"kw-clinique\">signes fonctionnels urinaires isolés</span> (notamment calculs <span class=\"kw-clinique\">intravésicaux</span>)</li>\n        <li><span class=\"kw-bio\">Leucocyturie</span></li>\n        <li><span class=\"kw-bio\">Hématurie microscopique</span> : très fréquente (<span class=\"kw-chiffre\">70–100 %</span>), facile à déceler à la <span class=\"kw-bio\">BU</span></li>\n        <li><span class=\"kw-bio\">Hématurie macroscopique</span> : plus rare, impose toujours de rechercher une <strong>autre cause</strong></li>\n        <li><span class=\"kw-alerte\">PNA obstructive</span>, syndrome septique sévère à gram négatif</li>\n        <li><span class=\"kw-clinique\">Insuffisance rénale aiguë</span> obstructive</li>\n        <li><span class=\"kw-etio\">Infection urinaire récidivante</span> (doit faire rechercher un calcul, sauf <span class=\"kw-clinique\">cystite</span> de la femme jeune)</li>\n        <li><span class=\"kw-clinique\">Insuffisance rénale chronique</span> par <span class=\"kw-def\">néphropathie interstitielle chronique</span> (rare ; obstacle chronique bilatéral, souvent silencieux)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1},{"id":"265-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une lithiase urinaire","contenu":"<p>Quatre modalités, choisies selon le <strong>contexte clinique</strong> et l'<strong>accessibilité</strong> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Apports</th><th>Limites</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">ASP</span></td><td>Calculs <span class=\"kw-imagerie\">radio-opaques</span> ; distingue <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">calcifications extra-urinaires</span> (phlébolithe, stercolithe)</td><td>Calculs <span class=\"kw-imagerie\">radio-transparents</span> non visibles</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie</span></td><td><span class=\"kw-imagerie\">Dilatation pyélocalicielle</span> d'amont ; <span class=\"kw-imagerie\">calcul hyperéchogène + cône d'ombre postérieur</span> ; ↑ index de résistivité, ↓ jet urétéral au Doppler</td><td>Opérateur-dépendante ; peu sensible pour <span class=\"kw-clinique\">les</span> <strong>petits calculs</strong> et la <strong>position urétérale</strong></td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM AP sans injection</span></td><td><strong>Examen de référence</strong> (<span class=\"kw-chiffre\">Se et Sp ≥ 96 %</span>) : tous calculs ; mesure de la <span class=\"kw-imagerie\">densité UH</span> ; <span class=\"kw-ttt\">infiltration</span> de la graisse péri-rénale ; anomalies urologiques</td><td>Examen <span class=\"kw-alerte\">ionisant</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM AP injectée</span> (uroscanner)</td><td>Diagnostics différentiels ; <span class=\"kw-imagerie\">asymétrie d'excrétion</span>, fuite de PDC (urinome)</td><td>Injection de PDC iodé</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Stratégie selon la forme clinique</strong> :</p>\n      <ul>\n        <li><strong>CN simple</strong> (imagerie &lt;<span class=\"kw-chiffre\"> 48 h</span>, sans <span class=\"kw-alerte\">urgence</span>) : <span class=\"kw-imagerie\">ASP + échographie</span>, ou <span class=\"kw-imagerie\">TDM AP sans injection</span></li>\n        <li><strong>Forme compliquée</strong> : <span class=\"kw-imagerie\">TDM AP sans injection en urgence</span></li>\n        <li><strong>Femme enceinte</strong> : <span class=\"kw-imagerie\">échographie</span> (± <span class=\"kw-imagerie\">ASP</span>) en 1ʳᵉ intention ; si non concluante → <span class=\"kw-imagerie\">TDM faible dose</span> réservée aux <span class=\"kw-clinique\">cas complexes</span>, après <span class=\"kw-clinique\">décision pluridisciplinaire</span></li>\n        <li><strong>Doute diagnostique</strong> : <span class=\"kw-imagerie\">TDM AP sans puis avec injection</span> (uroscanner)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Suivi</span>.</strong> Privilégier <span class=\"kw-clinique\">les</span> examens <strong>peu irradiants</strong> (<span class=\"kw-imagerie\">ASP + échographie</span>) ; ne pas multiplier les <span class=\"kw-imagerie\">TDM</span>.</div>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/urolithiasis","label":"Radiopaedia : Urolithiase"}]},{"id":"265-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques en urgence à réaliser devant une colique néphrétique","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">BU</span></td><td>Systématique</td></tr>\n          <tr><td><span class=\"kw-bio\">β-hCG</span></td><td>Toute <strong>femme en âge de procréer</strong> (éliminer une <span class=\"kw-ci\">grossesse</span> extra-utérine)</td></tr>\n          <tr><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">calcémie</span></td><td>Systématique (selon le CUEN)</td></tr>\n          <tr><td><span class=\"kw-bio\">ECBU</span></td><td>Si <span class=\"kw-bio\">BU</span> positive ou <span class=\"kw-alerte\">forme fébrile</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Hémocultures</span></td><td>Si <span class=\"kw-alerte\">forme fébrile</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexes.</strong> Devant toute CN : <span class=\"kw-bio\">β-hCG</span> chez la femme jeune, et recherche de <strong><span class=\"kw-alerte\">signes de gravité</span> biologiques</strong> — <span class=\"kw-bio\">créatinine</span> élevée (IRA) et <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> → forme fébrile).</div>","frequence":3},{"id":"265-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser pour le diagnostic étiologique de la lithiase urinaire","contenu":"<p><strong>Exploration métabolique</strong> indiquée chez <strong>tout patient lithiasique</strong> (y compris au 1ᵉʳ calcul), réalisée à <span class=\"kw-chiffre\">4–6 semaines</span> de l'épisode, dans <span class=\"kw-clinique\">les</span> conditions habituelles d'activité et d'alimentation.</p>\n      <table >\n        <thead><tr><th>Prélèvement</th><th>Paramètres (seuils lithogènes)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Sang</span></td><td><span class=\"kw-bio\">Créatininémie</span>, <span class=\"kw-bio\">urée</span> (fonction rénale) ; <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">uricémie</span> (syndrome métabolique) ; <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">phosphorémie</span> ; <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">bicarbonate</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Urines des 24 h</span></td><td>\n            <strong>Volume :</strong> <span class=\"kw-def\">facteur de risque</span> si <span class=\"kw-chiffre\">&lt; 2 L/24 h</span><br>\n            <strong>Calcium :</strong> hypercalciurie si <span class=\"kw-chiffre\">&gt; 0,1 mmol/kg/j</span> ou <span class=\"kw-chiffre\">&gt; 3,8 mmol/L</span><br>\n            <strong>Acide urique :</strong> FR si <span class=\"kw-chiffre\">&gt; 5 mmol/24 h</span><br>\n            <strong>Sodium :</strong> FR si <span class=\"kw-chiffre\">&gt; 150 mmol/24 h</span> (reflet de la consommation de sel)<br>\n            <strong><span class=\"kw-bio\">Urée</span> :</strong> FR si <span class=\"kw-chiffre\">&gt; 5,5 mmol/kg/24 h</span> (reflet de l'apport protidique)</td></tr>\n          <tr><td><span class=\"kw-bio\">Urines du matin</span></td><td><strong><span class=\"kw-bio\">pH</span> :</strong> <span class=\"kw-chiffre\">5</span> → lithiase urique ; <span class=\"kw-chiffre\">6,5</span> → phosphocalcique<br><strong>Densité :</strong> FR si <span class=\"kw-chiffre\">&gt; 1012</span><br><span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-bio\">cristallurie</span> (si le calcul n'a pas été recueilli)</td></tr>\n          <tr><td><span class=\"kw-bio\">Analyse du calcul</span></td><td><strong>Analyse morpho-constitutionnelle</strong> + <span class=\"kw-bio\">spectrophotométrie infrarouge</span> : cystine → <span class=\"kw-def\">cystinurie</span> ; oxalate type Ic → hyperoxalurie primaire ; <span class=\"kw-def\">brushite</span> → <span class=\"kw-etio\">hyperparathyroïdie primaire</span> ; struvite → lithiase d'infection ; carbapatite IVa2 → acidose tubulaire distale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Le calcul doit toujours être récupéré</strong> (miction sur passoire ou per-opératoire) : son analyse est l'examen étiologique le plus rentable. À défaut, <span class=\"kw-bio\">cristallurie</span> sur la 2ᵉ urine du matin.</div>\n      <p><strong>Bilan de 2ᵉ intention</strong> (anomalie du 1ᵉʳ bilan, ou forme secondaire probable : âge jeune, forme récidivante/familiale, composition particulière, néphrocalcinose) : ajout de <span class=\"kw-bio\">PTH</span>, <span class=\"kw-bio\">vitamine D</span>, <span class=\"kw-bio\">magnésémie</span>, oxalurie, citraturie, kaliurie.</p>","frequence":3},{"id":"265-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales anomalies métaboliques associées à des lithiases calciques","contenu":"<p>Deux anomalies dominent <span class=\"kw-clinique\">les</span> lithiases calciques : l'<span class=\"kw-def\">hypercalciurie</span> (la plus fréquente) et l'<span class=\"kw-def\">hyperoxalurie</span>.</p>\n      <p><strong><span class=\"kw-def\">Hypercalciurie</span></strong> — seuil <span class=\"kw-chiffre\">&gt; 0,1 mmol/kg/j</span> ou <span class=\"kw-chiffre\">&gt; 3,8 mmol/L</span> :</p>\n      <ul>\n        <li><strong>Avec <span class=\"kw-bio\">hypercalcémie</span></strong> → cause <span class=\"kw-etio\">secondaire</span> : <span class=\"kw-etio\">hyperparathyroïdie primaire</span>, ostéolyse maligne, intoxication à la <span class=\"kw-bio\">vitamine D</span>, hyperthyroïdie…</li>\n        <li><strong>Sans hypercalcémie</strong> : hyperparathyroïdie normocalcémique, <span class=\"kw-etio\">sarcoïdose</span>, fuite rénale de calcium (tubulopathie, <span class=\"kw-ttt\">furosémide</span>), origine osseuse (<span class=\"kw-clinique\">syndrome de Cushing</span>, <span class=\"kw-ttt\">corticothérapie</span>, acidose, hyperthyroïdie)</li>\n        <li><strong><span class=\"kw-def\">Idiopathique</span></strong> (nutritionnelle) : régime hypersodé (<span class=\"kw-chiffre\">&gt; 9 g/j</span>), riche en protéines (<span class=\"kw-chiffre\">&gt; 1,2 g/kg/j</span>), apports calciques élevés (<span class=\"kw-chiffre\">&gt; 1 g/j</span>)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> La <span class=\"kw-bio\">calciurie</span> peut être <span class=\"kw-alerte\">faussement normale ou basse</span> en cas d'<span class=\"kw-clinique\">insuffisance rénale</span>, d'apports calciques très faibles ou d'<span class=\"kw-clinique\">hypovitaminose D</span>.</div>\n      <p><strong><span class=\"kw-def\">Hyperoxalurie</span></strong> :</p>\n      <ul>\n        <li><strong>Excès de production</strong> : <span class=\"kw-def\">oxalose</span> (hyperoxalurie primaire, déficit enzymatique <span class=\"kw-etio\">congénital</span>)</li>\n        <li><strong>Excès d'apport / entérique</strong> : <span class=\"kw-etio\">diarrhées chroniques</span>, <span class=\"kw-etio\">MICI</span>, <span class=\"kw-etio\">maladie cœliaque</span>, résection iléale ; régime riche en oxalate</li>\n      </ul>\n      <p><span class=\"kw-def\">Physiopathologie</span> de l'hyperoxalurie entérique : la <span class=\"kw-clinique\">malabsorption des acides gras</span> entraîne une <strong>chélation du calcium</strong> par ces AG → l'<span class=\"kw-bio\">oxalate</span> reste libre et devient absorbable par l'intestin.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie</em></p>","frequence":0},{"id":"265-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge de la lithiase urinaire","contenu":"<p>Deux temps : <strong>traiter la crise</strong> (colique néphrétique), puis <strong>traiter le calcul à distance</strong> et <strong>prévenir la récidive</strong>.</p>\n\n      <p><strong>1 · Traitement de la colique néphrétique simple (ambulatoire)</strong></p>\n      <ul>\n        <li><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">kétoprofène</span> IV/IM (<span class=\"kw-ttt\">AINS</span>), relais per os après sédation de la douleur</li>\n        <li><span class=\"kw-ttt\">Paracétamol</span> ± <span class=\"kw-ttt\">tramadol</span> si douleur de faible intensité</li>\n        <li><span class=\"kw-ttt\">Morphine</span> IV titrée si échec ou <span class=\"kw-ci\">CI aux AINS</span></li>\n        <li><span class=\"kw-ttt\">α-bloquants</span> : thérapie médicale expulsive (TME) des calculs urétéraux distaux de <span class=\"kw-chiffre\">5–10 mm</span> — <span class=\"kw-ci\">hors AMM</span></li>\n        <li><strong>Restriction hydrique</strong> tant que le calcul n'est pas éliminé</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Colique néphrétique compliquée → <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">drainage</span>.</strong>\n        <ul>\n          <li><strong>Forme fébrile</strong> = <span class=\"kw-alerte\">PNA obstructive</span> : <span class=\"kw-ttt\">antibiothérapie IV (C3G + aminoside)</span> + <strong><span class=\"kw-ttt\">drainage</span> des urines en <span class=\"kw-alerte\">urgence</span></strong></li>\n          <li><strong>Formes hyperalgique / oligo-anurique</strong> : <strong><span class=\"kw-ttt\">drainage</span> des urines</strong></li>\n          <li><span class=\"kw-def\">Sonde double JJ</span> (voie endoscopique, AG) — vérifier l'absence d'<span class=\"kw-alerte\">hyperkaliémie menaçante</span> ; ou <span class=\"kw-def\">néphrostomie percutanée</span> (échoguidée, AL) si urines purulentes ou échec de la JJ — <span class=\"kw-ci\">CI si trouble de l'hémostase</span></li>\n        </ul>\n      </div>\n\n      <p><strong>2 · Traitement urologique du calcul (à distance, hors épisode aigu)</strong></p>\n      <table >\n        <thead><tr><th>Technique</th><th>Indications préférentielles</th><th><span class=\"kw-ci\">Contre-indications</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">LEC</span> (lithotritie extracorporelle)</td><td>Calculs urétéraux <span class=\"kw-chiffre\">&lt; 10 mm</span> ; calculs rénaux <span class=\"kw-chiffre\">&lt; 20 mm</span> (sauf calice inférieur)</td><td><span class=\"kw-ci\">Grossesse</span> ; <span class=\"kw-ci\">anticoagulants / troubles de l'hémostase</span> ; infection non traitée ; anévrisme aortique ; obstacle d'aval ; calcul dense (<span class=\"kw-chiffre\">&gt; 1000–1200 UH</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">URS</span> (urétéro-rénoscopie)</td><td>Calculs urétéraux même <span class=\"kw-chiffre\">&gt; 10 mm</span> ; calculs rénaux <span class=\"kw-chiffre\">&lt; 20 mm</span> ; calculs durs ; patient sous <span class=\"kw-ttt\">anticoagulants</span></td><td><span class=\"kw-ci\">Infection urinaire non traitée</span></td></tr>\n          <tr><td><span class=\"kw-def\">NLPC</span> (néphrolithotomie percutanée)</td><td>Calculs rénaux <span class=\"kw-chiffre\">&gt; 20 mm</span> / <span class=\"kw-def\">coralliformes</span> ; gros calculs urétéraux lombaires</td><td><span class=\"kw-ci\">Infection non traitée</span> ; <span class=\"kw-ci\">troubles de l'hémostase</span></td></tr>\n          <tr><td><span class=\"kw-def\">Chirurgie</span> (ouverte / cœlioscopie)</td><td>Très gros calculs (&lt; <span class=\"kw-chiffre\">0,5 %</span> des cas) ; malformation associée à traiter</td><td><span class=\"kw-ci\">Troubles de l'hémostase non corrigés</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications selon la taille</strong> : ≤ <span class=\"kw-chiffre\">6 mm</span> → <span class=\"kw-def\">surveillance</span> si asymptomatique, sinon URS/LEC ; <span class=\"kw-chiffre\">7–15 mm</span> → URS ou LEC ; <span class=\"kw-chiffre\">15–20 mm</span> → LEC ou NLPC ; <span class=\"kw-chiffre\">&gt; 20 mm</span> → NLPC.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/265/algorithme-calcul-renal.png\" alt=\"Algorithme de prise en charge d'un calcul rénal selon sa taille et sa localisation : calice inférieur, autres calices, bassinet, calculs multiples\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Algorithme — calcul rénal</span> selon la taille et la localisation (lorsqu'un traitement est indiqué) : surveillance, <span class=\"kw-def\">LEC</span>, endourologie (<span class=\"kw-def\">URS</span>) ou <span class=\"kw-def\">NLPC</span>. Source : recommandations CLAFU 2022, Collège d'urologie — fiche source EDN item 265.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/265/algorithme-calcul-ureteral.png\" alt=\"Algorithme de prise en charge d'un calcul urétéral hors urgence et en l'absence d'infection urinaire : siège proximal ou distal, symptomatique ou non, seuil de 10 mm\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Algorithme — calcul urétéral</span> hors <span class=\"kw-alerte\">urgence</span> et sans infection : selon le siège (proximal/distal), le caractère symptomatique et la taille (seuil <span class=\"kw-chiffre\">10 mm</span>) → surveillance/TME, <span class=\"kw-def\">LEC</span>, <span class=\"kw-def\">URS</span> ou <span class=\"kw-imagerie\">endoscopie</span>. Source : recommandations CLAFU 2022, Collège d'urologie — fiche source EDN item 265.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\"><strong>Femme enceinte.</strong> <span class=\"kw-ci\">AINS contre-indiqués</span> (surtout au 3ᵉ trimestre) ; <span class=\"kw-ttt\">paracétamol</span> et <span class=\"kw-ttt\">morphiniques</span> (hors travail) autorisés ; imagerie = <span class=\"kw-imagerie\">échographie</span> ; <strong><span class=\"kw-ttt\">drainage</span></strong> (JJ / néphrostomie) pour temporiser jusqu'à l'accouchement ; <span class=\"kw-ci\">LEC contre-indiquée</span>.</div>\n\n      <p><strong>3 · Traitement médical préventif (selon le type de calcul)</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Hydratation</th><th>Mesures spécifiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Oxalo-calcique</span></td><td><span class=\"kw-chiffre\">≥ 2 L/j</span></td><td>Maintien des apports calciques <span class=\"kw-chiffre\">~1 g/j</span> (pas de restriction → risque d'ostéoporose) ; réduire <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">oxalates</span> ; eau adaptée à la consommation de laitages</td></tr>\n          <tr><td><span class=\"kw-def\">Urique</span></td><td><span class=\"kw-chiffre\">≥ 2 L/j</span></td><td><span class=\"kw-def\">Alcalinisation</span> des urines (objectif <span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">6–7</span>) → dissolution du calcul en <span class=\"kw-chiffre\">1–3 mois</span> ; <span class=\"kw-ttt\">réduction</span> des purines ; <span class=\"kw-ttt\">allopurinol</span> si hyperuricémie</td></tr>\n          <tr><td><span class=\"kw-def\">Cystinique</span></td><td><span class=\"kw-chiffre\">≥ 3–4 L/j</span></td><td>Diurèse alcaline (<span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">&gt; 7,5</span>) ; régime pauvre en sel et en méthionine ; <span class=\"kw-ttt\">D-pénicillamine</span> si échec</td></tr>\n          <tr><td><span class=\"kw-def\">Infection (struvite)</span></td><td>—</td><td><strong>Ablation complète du calcul</strong> + stérilisation urinaire prolongée par <span class=\"kw-ttt\">antibiothérapie</span> adaptée</td></tr>\n        </tbody>\n      </table>\n      <p>Mesures générales : <span class=\"kw-clinique\">activité physique</span> régulière, apport en <span class=\"kw-bio\">citrate</span> (agrumes, légumes), limitation du <span class=\"kw-bio\">sel</span> (<span class=\"kw-chiffre\">~7 g/j</span>), des <span class=\"kw-bio\">protéines animales</span> (<span class=\"kw-chiffre\">&lt; 1 g/kg/j</span>) et des sucres rapides.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span></em></p>","frequence":9}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> la <span class=\"kw-clinique\">colique néphrétique simple</span> (<span class=\"kw-chiffre\">95 %</span>) est une <span class=\"kw-alerte\">urgence antalgique</span> prise en charge en ambulatoire ; la <span class=\"kw-alerte\">forme compliquée</span> (<span class=\"kw-chiffre\">5 %</span>) impose une <span class=\"kw-alerte\">hospitalisation</span> en urgence.<br><strong>Fenêtre imagerie :</strong> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">< 48 h</span> si CN simple ; <span class=\"kw-imagerie\">TDM AP sans injection</span> en <span class=\"kw-alerte\">urgence</span> si forme compliquée.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">kétoprofène IV/IM</span> (<span class=\"kw-ttt\">AINS</span>) en 1ère intention.</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">colique néphrétique simple</span> (<span class=\"kw-chiffre\">95 %</span>), apyrétique, abdomen souple, fonction rénale normale.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> :</strong> toute <span class=\"kw-alerte\">forme compliquée</span> (fébrile, oligo-anurique, hyperalgique) ou <span class=\"kw-etio\">terrain à risque</span> → <span class=\"kw-ttt\">avis urologique</span> + <span class=\"kw-ttt\">drainage des urines</span>.<br><strong>Qui draine ?</strong> urologue, par <span class=\"kw-ttt\">sonde double JJ</span> (<span class=\"kw-imagerie\">endoscopie</span>, AG) ou <span class=\"kw-ttt\">néphrostomie percutanée</span> (AL, écho).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre > 38 °C</span>, <span class=\"kw-clinique\">frissons</span> → <span class=\"kw-alerte\">PNA obstructive</span> (rétention purulente en amont de l'obstacle) : risque d'<span class=\"kw-alerte\">abcès du rein</span> et de <span class=\"kw-alerte\">choc septique</span> à gram négatif</li><li><span class=\"kw-alerte\">Oligo-anurie / insuffisance rénale aiguë</span> : <span class=\"kw-etio\">IRA obstructive</span> sur obstacle bilatéral ou sur rein unique</li><li><span class=\"kw-alerte\">Forme hyperalgique</span> résistante au traitement médical bien conduit</li><li><span class=\"kw-etio\">Terrain à risque</span> : <span class=\"kw-clinique\">grossesse</span>, rein unique, <span class=\"kw-etio\">insuffisance rénale chronique</span>, rein transplanté, <span class=\"kw-etio\">VIH</span> sous antiprotéases (<span class=\"kw-ttt\">indinavir</span>, <span class=\"kw-ttt\">atazanavir</span>), uropathie connue</li><li><span class=\"kw-clinique\">Arrêt brutal de la douleur</span> : expulsion du calcul, mais aussi possible <span class=\"kw-alerte\">rupture d'un fornix rénal</span> avec extravasation d'urine péri-rénale</li></ul>","principes":"<p>Antalgie de la <span class=\"kw-clinique\">colique néphrétique</span> simple, <span class=\"kw-ttt\">drainage des urines</span> en <span class=\"kw-alerte\">urgence</span> si forme compliquée, puis traitement urologique du <span class=\"kw-etio\">calcul</span> à distance.</p><p><strong>Antalgie de la CN simple (ambulatoire)</strong></p><ul><li><span class=\"kw-ttt\">Kétoprofène</span> IV/IM (<span class=\"kw-ttt\">AINS</span>) en <span class=\"kw-chiffre\">1ère intention</span>, relais per os après sédation</li><li><span class=\"kw-ttt\">Paracétamol</span> ± <span class=\"kw-ttt\">tramadol</span> si douleur de faible intensité</li><li><span class=\"kw-ttt\">Morphine</span> IV titrée si échec du traitement initial ou <span class=\"kw-ci\">CI aux AINS</span></li><li><span class=\"kw-ttt\">α-bloquants</span> (thérapie médicale expulsive, hors AMM) pour <span class=\"kw-clinique\">les</span> calculs urétéraux distaux de <span class=\"kw-chiffre\">5 à 10 mm</span></li><li>Restriction hydrique tant que le calcul n'est pas éliminé</li></ul><p><strong>CN compliquée — <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">urgence</span></strong></p><p><span class=\"kw-ttt\">Drainage</span> en <span class=\"kw-alerte\">urgence</span>, choix sonde JJ <span class=\"kw-bio\">vs</span> néphrostomie au cas par cas.</p><ul><li>Forme <span class=\"kw-clinique\">fébrile</span> = <span class=\"kw-alerte\">PNA obstructive</span> : <span class=\"kw-ttt\">ATB IV</span> (<span class=\"kw-ttt\">C3G + aminoside</span>) + <span class=\"kw-ttt\">drainage des urines</span></li><li>Forme <span class=\"kw-alerte\">hyperalgique</span> ou <span class=\"kw-alerte\">oligo-anurique</span> : <span class=\"kw-ttt\">drainage des urines</span></li><li><span class=\"kw-ttt\">Sonde double JJ</span> : poser après avoir vérifié l'absence d'<span class=\"kw-ci\">hyperkaliémie menaçante</span></li><li><span class=\"kw-ttt\">Néphrostomie percutanée</span> : en l'absence d'<span class=\"kw-ci\">anticoagulant ou de trouble de l'hémostase</span></li></ul><p><strong>Traitement urologique du calcul (à distance)</strong></p><p>À distance de l'épisode aigu, après recherche d'<span class=\"kw-clinique\">infection urinaire</span>, de trouble de l'hémostase et d'anomalie urologique.</p><ul><li>Calcul <span class=\"kw-chiffre\">≤ 6 mm</span> : <span class=\"kw-def\">surveillance</span> si asymptomatique, <span class=\"kw-ttt\">urétéroscopie</span> ou <span class=\"kw-ttt\">LEC</span> si symptomatique</li><li>Calcul <span class=\"kw-chiffre\">7–15 mm</span> : <span class=\"kw-ttt\">urétéroscopie</span> ou <span class=\"kw-ttt\">LEC</span></li><li>Calcul <span class=\"kw-chiffre\">15–20 mm</span> : <span class=\"kw-ttt\">LEC</span> ou <span class=\"kw-ttt\">NLPC</span></li><li>Calcul <span class=\"kw-chiffre\">> 20 mm</span> / coralliforme : <span class=\"kw-ttt\">NLPC</span></li><li>Calcul radio-transparent (<span class=\"kw-etio\">acide urique</span>) : tenter d'abord l'<span class=\"kw-ttt\">alcalinisation des urines</span></li></ul><p><strong>Femme enceinte</strong></p><ul><li><span class=\"kw-ci\">AINS contre-indiqués</span> (surtout au 3e trimestre)</li><li><span class=\"kw-ttt\">Paracétamol</span> et morphiniques (hors travail) autorisés</li><li><span class=\"kw-imagerie\">Échographie</span> rénale et pelvienne en priorité ; <span class=\"kw-imagerie\">TDM</span> faible dose réservée aux cas complexes</li><li>Si échec du traitement médical : <span class=\"kw-ttt\">drainage des urines</span> pour temporiser (risque d'<span class=\"kw-alerte\">accouchement prématuré</span>), traitement du calcul après l'accouchement (<span class=\"kw-ci\">LEC contre-indiquée</span>)</li></ul>","suivi":"<p><strong>Imagerie :</strong> après une CN d'<span class=\"kw-clinique\">évolution</span> favorable, <span class=\"kw-imagerie\">ASP + échographie</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 semaines</span> ; après <span class=\"kw-chiffre\">4 à 6 semaines</span>, si le calcul persiste → traitement spécifique (un calcul <span class=\"kw-chiffre\">> 8–10 mm</span> ne s'élimine quasi jamais).<br><strong>Récupérer le calcul :</strong> tamiser les urines pour l'<span class=\"kw-bio\">analyse morpho-constitutionnelle</span>.<br><strong>Bilan métabolique :</strong> à <span class=\"kw-chiffre\">4–6 semaines</span> de l'épisode ; sans prévention, <span class=\"kw-etio\">récidive</span> dans <span class=\"kw-chiffre\">50 %</span> à<span class=\"kw-chiffre\"> 5 ans</span> et <span class=\"kw-chiffre\">70 %</span> à<span class=\"kw-chiffre\"> 10 ans</span>.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-14-item-265-lithiase-urinaire/","label":"Urofrance : Collège d'urologie — item 265 (lithiase urinaire)"},{"href":"https://manuel4.cuen.fr/spip.php?rubrique25","label":"CUEN : manuel de néphrologie en ligne"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de colique néphrétique — Douleur lombo-abdominale aiguë, unilatérale, paroxystique, sans position antalgique","detail":"<h4>CAT — Colique néphrétique — Orientation devant une suspicion de colique néphrétique sur calcul</h4>","branches":[{"to":"q-gravite","label":"Antalgie + biologie en urgence","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Critère de gravité ? — Fièvre, oligo-anurie/IRA, douleur réfractaire ou terrain à risque","branches":[{"to":"t-simple","label":"Aucun critère de gravité (95 %)","color":"green"},{"to":"q-type","label":"≥ 1 critère présent (5 %)","color":"red"}]},{"id":"t-simple","kind":"terminal","label":"CN simple → ambulatoire","color":"green","detail":"<h4>Paraclinique</h4><ul><li>Biologie en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">BU</span> ; <span class=\"kw-bio\">β-hCG</span> si femme en âge de procréer</li><li>Imagerie dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">< 48 h</span> : <span class=\"kw-imagerie\">ASP + échographie</span> ou <span class=\"kw-imagerie\">TDM AP sans injection</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Kétoprofène</span> IV/IM (<span class=\"kw-ttt\">AINS</span>) en 1ère intention, relais per os</li><li><span class=\"kw-ttt\">Morphine</span> IV titrée si échec ou <span class=\"kw-ci\">CI aux AINS</span></li><li>Restriction hydrique tant que le calcul n'est pas éliminé</li></ul>"},{"id":"q-type","kind":"decision","label":"Quelle complication / quel terrain ? — Oriente le geste d'urgence","branches":[{"to":"t-pna","label":"Fièvre > 38 °C","color":"red"},{"to":"t-ira","label":"Oligo-anurie / IRA","color":"red"},{"to":"t-hyperalgie","label":"Douleur réfractaire","color":"red"},{"to":"t-grossesse","label":"Grossesse","color":"amber"}]},{"id":"t-pna","kind":"terminal","label":"PNA obstructive → ATB + drainage en urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre > 38 °C</span>, <span class=\"kw-clinique\">frissons</span> : <span class=\"kw-alerte\">PNA obstructive</span> (rétention purulente en amont de l'obstacle)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">ATB IV</span> : <span class=\"kw-ttt\">C3G + aminoside</span></li><li><span class=\"kw-ttt\">Drainage des urines</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">sonde JJ</span> ou <span class=\"kw-ttt\">néphrostomie percutanée</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-alerte\">choc septique</span> à gram négatif et d'<span class=\"kw-alerte\">abcès du rein</span></li></ul>"},{"id":"t-ira","kind":"terminal","label":"IRA obstructive → drainage en urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Oligo-anurie</span>, <span class=\"kw-etio\">insuffisance rénale aiguë obstructive</span> (obstacle bilatéral ou sur rein unique)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage des urines</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Sonde double JJ</span> après contrôle de l'absence d'<span class=\"kw-ci\">hyperkaliémie menaçante</span></li></ul>"},{"id":"t-hyperalgie","kind":"terminal","label":"Forme hyperalgique → drainage des urines","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Douleur réfractaire</span> au traitement médical bien conduit</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage des urines</span> (<span class=\"kw-ttt\">sonde JJ</span> ou <span class=\"kw-ttt\">néphrostomie percutanée</span>)</li></ul>"},{"id":"t-grossesse","kind":"terminal","label":"Grossesse → PEC spécifique","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> rénale et pelvienne en priorité (limiter l'<span class=\"kw-clinique\">irradiation</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ci\">AINS contre-indiqués</span> (surtout au 3e trimestre) ; <span class=\"kw-ttt\">paracétamol</span> et morphiniques autorisés</li></ul><h4>Conduite</h4><ul><li>Si échec : <span class=\"kw-ttt\">drainage</span> pour temporiser (risque d'<span class=\"kw-alerte\">accouchement prématuré</span>) ; traitement du calcul après l'accouchement (<span class=\"kw-ci\">LEC contre-indiquée</span>)</li></ul>"}]},"cards":[{"i":"3612e9aebb41","n":265,"o":"265-1","u":"Définition","t":"Connaître la définition de la lithiase et du calcul urinaires","q":"Quelle est la définition de la lithiase urinaire ?","a":"<p>La lithiase urinaire est une <strong>maladie multifactorielle</strong> caractérisée par la formation de <strong>calculs</strong> dans les <strong>voies urinaires</strong> (cavités rénales, uretères, plus rarement vessie et urètre).</p>"},{"i":"98d0236d0365","n":265,"o":"265-1","u":"Définition","t":"Connaître la définition de la lithiase et du calcul urinaires","q":"Quelle est la définition d'un calcul urinaire ?","a":"<p>Le calcul urinaire est une <strong>concrétion solide</strong>, composée de minéraux et/ou de matières organiques, qui se forme dans les voies urinaires. Il correspond au support physique de la lithiase.</p>"},{"i":"ee92afab5183","n":265,"o":"265-1","u":"Définition","t":"Connaître la définition de la lithiase et du calcul urinaires","q":"Quelle est la composition typique d'un calcul urinaire ?","a":"<ul><li>Les calculs sont composés de minéraux (<strong>calcium, phosphates, magnésium</strong>) et/ou de matières organiques (<strong>oxalate, acide urique, cystine</strong>).</li><li>Dans 90% des cas, ils contiennent <strong>plusieurs composés</strong>, avec un composant majoritaire (ex: oxalate de calcium).</li><li>Le calcul <strong>coralliforme</strong> occupe la totalité des cavités pyélocalicielles.</li></ul>"},{"i":"161f086bd3c7","n":265,"o":"265-11","u":"Examens complémentaires","t":"Connaître les examens biologiques en urgence à réaliser devant une colique néphrétique","q":"Quelle est l'indication spécifique de la β-hCG chez une patiente présentant une colique néphrétique ?","a":"<p>La <strong>β-hCG</strong> est indiquée chez <strong>toute femme en âge de procréer</strong> présentant une colique néphrétique afin d'éliminer une <strong>grossesse extra-utérine (GEU)</strong>.</p>"},{"i":"361becb4a030","n":265,"o":"265-11","u":"Examens complémentaires","t":"Connaître les examens biologiques en urgence à réaliser devant une colique néphrétique","q":"Dans quelles situations un ECBU et des hémocultures sont-ils indiqués en urgence lors d'une colique néphrétique ?","a":"<ul><li>Un <strong>ECBU</strong> (Examen CytoBactériologique des Urines) est indiqué si la <strong>bandelette urinaire (BU) est positive</strong> ou en cas de <strong>forme fébrile</strong> de colique néphrétique.</li><li>Des <strong>hémocultures</strong> sont indiquées si la colique néphrétique se présente sous une <strong>forme fébrile</strong>.</li></ul>"},{"i":"e4aebe437473","n":265,"o":"265-11","u":"Examens complémentaires","t":"Connaître les examens biologiques en urgence à réaliser devant une colique néphrétique","q":"Quels sont les signes biologiques de gravité à rechercher en urgence devant une colique néphrétique ?","a":"<p>Les signes biologiques de gravité à rechercher en urgence sont :</p><ul><li>Une <strong>créatinine élevée</strong>, signe d'une <strong>insuffisance rénale aiguë (IRA)</strong>.</li><li>Un <strong>syndrome inflammatoire</strong>, objectivé par une <strong>NFS</strong> et une <strong>CRP</strong> élevées, orientant vers une <strong>forme fébrile</strong> de colique néphrétique.</li></ul>"},{"i":"efebb8fd2bc3","n":265,"o":"265-11","u":"Examens complémentaires","t":"Connaître les examens biologiques en urgence à réaliser devant une colique néphrétique","q":"Quels sont les examens biologiques systématiques à réaliser en urgence devant une colique néphrétique selon le contenu fourni ?","a":"<p>Devant une colique néphrétique en urgence, les examens biologiques systématiques à réaliser sont :</p><ul><li>Un <strong>ionogramme sanguin</strong>, avec <strong>créatinine</strong> et <strong>urée</strong>.</li><li>Une <strong>bandelette urinaire (BU)</strong>.</li><li>Une <strong>numération formule sanguine (NFS)</strong> et une <strong>protéine C réactive (CRP)</strong>, systématiquement selon le CUEN.</li></ul>"},{"i":"23db9459c590","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelle est la prise en charge initiale d'une colique néphrétique simple ?","a":"<p>La prise en charge initiale, en ambulatoire, d'une colique néphrétique simple repose sur :</p><ul><li>En première intention : l'administration de <strong>kétoprofène IV/IM</strong> (AINS), avec un relais per os après sédation de la douleur.</li><li>Si la douleur est de faible intensité : <strong>paracétamol</strong>, éventuellement associé à du <strong>tramadol</strong>.</li><li>En cas d'échec des traitements précédents ou de contre-indication aux AINS : <strong>morphine IV titrée</strong>.</li><li>Une <strong>restriction hydrique</strong> est recommandée tant que le calcul n'est pas éliminé.</li><li>Une <strong>thérapie médicale expulsive</strong> (TME) par <strong>alpha-bloquants</strong> peut être proposée (hors AMM) pour les calculs urétéraux distaux de 5 à 10 mm.</li></ul>"},{"i":"48ccea5dc3d4","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Comment gère-t-on la lithiase urinaire chez la femme enceinte ?","a":"<p>La prise en charge de la lithiase urinaire chez la femme enceinte implique des adaptations spécifiques :</p><ul><li>Les <strong>AINS sont contre-indiqués</strong>, surtout au 3ème trimestre.</li><li>Le <strong>paracétamol et les morphiniques</strong> (hors travail) sont autorisés.</li><li>L'imagerie de choix est l'<strong>échographie</strong>.</li><li>Un <strong>drainage</strong> par sonde double JJ ou néphrostomie est privilégié pour temporiser jusqu'à l'accouchement.</li><li>La <strong>LEC est contre-indiquée</strong>.</li></ul>"},{"i":"589f2e63eddd","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelles sont les principales techniques de traitement urologique des calculs à distance, hors épisode aigu ?","a":"<p>Les principales techniques de traitement urologique des calculs, à distance et hors épisode aigu, sont :</p><ul><li>La <strong>lithotritie extracorporelle (LEC)</strong> : indiquée préférentiellement pour les calculs urétéraux < 10 mm et rénaux < 20 mm (sauf calice inférieur). Contre-indiquée en cas de grossesse, troubles de l'hémostase, infection non traitée, anévrisme aortique, obstacle d'aval, ou calcul très dense (> 1000-1200 UH).</li><li>L'<strong>urétéro-rénoscopie (URS)</strong> : indiquée pour les calculs urétéraux (même > 10 mm) et rénaux < 20 mm, les calculs durs, ou chez les patients sous anticoagulants. Contre-indiquée en cas d'infection urinaire non traitée.</li><li>La <strong>néphrolithotomie percutanée (NLPC)</strong> : indiquée pour les calculs rénaux > 20 mm ou coralliformes, et les gros calculs urétéraux lombaires. Contre-indiquée en cas d'infection non traitée ou de troubles de l'hémostase.</li><li>La <strong>chirurgie (ouverte/cœlioscopie)</strong> : très rarement indiquée (< 0,5 % des cas) pour les très gros calculs ou en cas de malformation associée à traiter. Contre-indiquée si troubles de l'hémostase non corrigés.</li></ul>"},{"i":"62ffe11b1c33","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Comment prend-on en charge une colique néphrétique compliquée ?","a":"<p>Une colique néphrétique compliquée justifie une <strong>hospitalisation en urgence</strong> et un <strong>drainage des urines</strong> :</p><ul><li><strong>Forme fébrile</strong> (Pyélonéphrite aiguë obstructive) : <strong>antibiothérapie IV</strong> (C3G + aminoside) et <strong>drainage des urines en urgence</strong>.</li><li><strong>Forme hyperalgique ou oligo-anurique</strong> : <strong>drainage des urines</strong>.</li></ul><p>Les méthodes de drainage sont :</p><ul><li>La <strong>sonde double JJ</strong> (voie endoscopique, sous anesthésie générale), après vérification de l'absence d'hyperkaliémie menaçante.</li><li>La <strong>néphrostomie percutanée</strong> (échoguidée, sous anesthésie locale) en cas d'urines purulentes ou d'échec de la sonde JJ. Elle est contre-indiquée en cas de troubles de l'hémostase.</p></ul>"},{"i":"b5ff299f9281","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelles sont les mesures spécifiques de prévention de la récidive pour les calculs oxalo-calciques ?","a":"<p>Pour prévenir la récidive de calculs oxalo-calciques, les mesures spécifiques sont :</p><ul><li>Une <strong>hydratation ≥ 2 L/j</strong>.</li><li>Le <strong>maintien des apports calciques (~1 g/j)</strong>, sans restriction excessive pour éviter le risque d'ostéoporose.</li><li>La <strong>réduction des oxalates</strong> dans l'alimentation.</li><li>Une <strong>eau adaptée à la consommation de laitages</strong>.</li></ul>"},{"i":"d7bba86eff6c","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelles sont les mesures spécifiques de prévention de la récidive pour les calculs uriques ?","a":"<p>Pour prévenir la récidive de calculs uriques, les mesures spécifiques sont :</p><ul><li>Une <strong>hydratation ≥ 2 L/j</strong>.</li><li>L'<strong>alcalinisation des urines</strong> (objectif pH 6-7) pour favoriser la dissolution du calcul en 1 à 3 mois.</li><li>La <strong>réduction des purines</strong> dans l'alimentation.</li><li>L'<strong>allopurinol</strong> en cas d'hyperuricémie associée.</li></ul>"},{"i":"e4e6cc1a9e4d","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelles sont les mesures générales de prévention de la récidive de lithiase urinaire, quel que soit le type de calcul ?","a":"<p>Les mesures générales de prévention de la récidive de lithiase urinaire, applicables quel que soit le type de calcul, incluent :</p><ul><li>Une <strong>activité physique régulière</strong>.</li><li>Un <strong>apport en citrate</strong> par la consommation d'agrumes et de légumes.</li><li>La <strong>limitation du sel</strong> (~7 g/j).</li><li>La <strong>limitation des protéines animales</strong> (< 1 g/kg/j).</li><li>La <strong>limitation des sucres rapides</strong>.</li></ul>"},{"i":"e917c3b22f82","n":265,"o":"265-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la lithiase urinaire","q":"Quelles sont les mesures spécifiques de prévention de la récidive pour les calculs cystiniques ?","a":"<p>Pour prévenir la récidive de calculs cystiniques, les mesures spécifiques sont :</p><ul><li>Une <strong>hydratation ≥ 3-4 L/j</strong>.</li><li>Une <strong>diurèse alcaline</strong> (pH > 7,5).</li><li>Un <strong>régime pauvre en sel et en méthionine</strong>.</li><li>L'administration de <strong>D-pénicillamine</strong> si les mesures précédentes échouent.</li></ul>"},{"i":"2650797c2eb3","n":265,"o":"265-5","u":"Diagnostic positif","t":"Connaître la définition de la colique néphrétique","q":"Quelle est la définition clinique de la colique néphrétique ?","a":"<p>La colique néphrétique (CN) est un <strong>syndrome douloureux aigu lombo-abdominal</strong>.</p>"},{"i":"92a42231fb36","n":265,"o":"265-5","u":"Diagnostic positif","t":"Connaître la définition de la colique néphrétique","q":"Quel mécanisme physiologique explique la douleur de la colique néphrétique ?","a":"<p>Le mécanisme est la <strong>mise en tension brutale</strong> de la voie excrétrice supérieure.</p>"},{"i":"9b9260ce7995","n":265,"o":"265-5","u":"Diagnostic positif","t":"Connaître la définition de la colique néphrétique","q":"À quelle situation anatomique la colique néphrétique est-elle toujours liée ?","a":"<p>Elle est toujours liée à une <strong>obstruction aiguë</strong>, +/- complète, de la voie excrétrice, quelle qu'en soit la cause.</p>"},{"i":"386deb22ad69","n":265,"o":"265-6","u":"Diagnostic positif","t":"Connaître les facteurs favorisants de la colique néphrétique","q":"Quels sont les facteurs liés aux circonstances de vie pouvant favoriser une colique néphrétique ?","a":"Les facteurs liés aux circonstances de vie incluent un <strong>voyage récent et prolongé</strong> ou une <strong>immobilisation prolongée</strong>."},{"i":"77e983282e5c","n":265,"o":"265-6","u":"Diagnostic positif","t":"Connaître les facteurs favorisants de la colique néphrétique","q":"Comment l'activité physique et les habitudes alimentaires peuvent-elles influencer le déclenchement d'une colique néphrétique ?","a":"Une <strong>activité physique intense</strong> et des <strong>écarts de régime</strong> peuvent favoriser le déclenchement d'une colique néphrétique."},{"i":"80d36f652cea","n":265,"o":"265-6","u":"Diagnostic positif","t":"Connaître les facteurs favorisants de la colique néphrétique","q":"Quelle est l'importance de l'hydratation et de la température ambiante dans la survenue d'une colique néphrétique ?","a":"Une <strong>déshydratation</strong>, une <strong>chaleur environnementale</strong> associée à des <strong>boissons insuffisantes</strong> sont des facteurs favorisants de colique néphrétique."},{"i":"9aba83319ef8","n":265,"o":"265-6","u":"Diagnostic positif","t":"Connaître les facteurs favorisants de la colique néphrétique","q":"Quel est le mécanisme physiologique commun par lequel ces facteurs favorisent la colique néphrétique ?","a":"Ces facteurs convergent vers une <ul><li><strong>réduction de la diurèse</strong></li><li>une <strong>concentration des urines</strong></li></ul> qui favorisent la mobilisation d'un calcul préexistant et la mise en tension de la voie excrétrice."},{"i":"4a7623ba2a89","n":265,"o":"265-7","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique simple","q":"Quels sont les signes cliniques qui permettent d'affirmer le caractère simple d'une colique néphrétique ?","a":"<p>Les signes cliniques qui caractérisent une colique néphrétique simple sont l'<strong>absence de fièvre</strong>, un abdomen <strong>souple sans défense</strong> et des touchers pelviens <strong>normaux</strong>. La présence de l'un de ces signes doit faire reconsidérer la simplicité de la colique néphrétique.</p>"},{"i":"9c8d3fa47c95","n":265,"o":"265-7","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique simple","q":"Quels sont les signes d'accompagnement fréquemment retrouvés lors d'une colique néphrétique simple ?","a":"<p>La colique néphrétique simple s'accompagne souvent :</p><ul><li>D'une <strong>anxiété</strong> et d'une <strong>agitation</strong> (le patient ne trouve aucune position antalgique).</li><li>De signes digestifs (dus à un iléus réflexe) : <strong>nausées, vomissements, constipation</strong>.</li><li>De signes urinaires : <strong>pollakiurie, impériosités, dysurie, hématurie microscopique</strong> à la bandelette urinaire (présente dans <strong>95%</strong> des cas à J1).</li><li>Il n'y a <strong>aucune position antalgique</strong>.</li><li>On retrouve une douleur à la palpation et à la percussion de la fosse lombaire.</li></ul>"},{"i":"ade168ba5265","n":265,"o":"265-7","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique simple","q":"Quelles sont les caractéristiques principales de la douleur dans la colique néphrétique simple ?","a":"<p>La douleur de la colique néphrétique simple est caractérisée par :</p><ul><li>Un début <strong>brutal</strong>.</li><li>Une intensité <strong>très intense</strong>.</li><li>Une évolution <strong>paroxystique</strong>.</li><li>Un type <strong>torsion</strong>.</li><li>Elle est <strong>unilatérale</strong>, lombaire ou de l'angle costo-vertébral.</li></ul>"},{"i":"e5c0b267024b","n":265,"o":"265-7","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique simple","q":"Comment irradie typiquement la douleur de la colique néphrétique simple ?","a":"<p>La douleur de la colique néphrétique simple irradie de manière <strong>antérieure et oblique</strong> vers la racine de la cuisse et les organes génitaux externes (OGE).</p>"},{"i":"1a25f0e02aad","n":265,"o":"265-8","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique compliquée","q":"Qu'est-ce qu'une colique néphrétique compliquée ?","a":"<p>Une colique néphrétique compliquée est une situation d'<strong>urgence</strong> qui survient dans environ <strong>5 % des cas</strong> de colique néphrétique. Elle justifie un avis spécialisé et une hospitalisation en urgence.</p>"},{"i":"23e97077233d","n":265,"o":"265-8","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique compliquée","q":"Comment une colique néphrétique peut-elle se compliquer d'une oligo-anurie ou d'une insuffisance rénale aiguë (IRA) ?","a":"<ul><li>L'IRA peut compliquer une <strong>PNA obstructive</strong> ou survenir dans un contexte de <strong>choc septique</strong>.</li><li>Il peut s'agir d'une <strong>IRA obstructive</strong> en cas d'obstacle bilatéral, ou unilatéral sur un rein unique (anatomique ou fonctionnel).</li></ul>"},{"i":"3588cf32068f","n":265,"o":"265-8","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique compliquée","q":"Quelle est la signification d'une fièvre (> 38°C) au cours d'une colique néphrétique ?","a":"<p>Une fièvre > 38°C évoque une <strong>pyélonéphrite aiguë obstructive</strong> (PNA obstructive). Cela correspond à une rétention d'urine purulente en amont de l'obstacle, avec un risque majeur d'<strong>abcès du rein</strong> et de <strong>septicémie/choc septique à gram négatif</strong>.</p>"},{"i":"95bc4ad4d6ab","n":265,"o":"265-8","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique compliquée","q":"Quels sont les terrains à risque d'une colique néphrétique compliquée ?","a":"<ul><li>La <strong>grossesse</strong>.</li><li>Un patient <strong>VIH sous antiprotéases</strong> (ex: indinavir, atazanavir).</li><li>Un <strong>rein unique</strong>.</li><li>Une <strong>uropathie connue</strong>.</li><li>Une <strong>insuffisance rénale chronique</strong>.</li><li>Un <strong>rein transplanté</strong>.</li></ul>"},{"i":"a579dcd8f03f","n":265,"o":"265-8","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la colique néphrétique compliquée","q":"Quelles sont les quatre situations qui définissent une colique néphrétique compliquée ?","a":"<ul><li>La présence d'un <strong>terrain à risque</strong>.</li><li>La présence de <strong>fièvre</strong> (> 38°C).</li><li>Une <strong>oligo-anurie ou une insuffisance rénale aiguë (IRA)</strong>.</li><li>Une <strong>forme hyperalgique</strong> (douleur résistante au traitement médical bien conduit).</li></ul>"}]};